1	// TK-402 П-28 v3.1: ядро событийной ленты step2 (Gate x Bybit). gcc -O2 -shared -fPIC -o tk402-step2-core.so tk402-step2-core.c -lm
2	// Лента = объединённые мс-времена ts[M] (события Gate, Bybit, границы разрывов); состояние (gb,ga,bb,ba) и ok[] — as-of на каждой метке (готовит питон).
3	// d[i] = лог-разница середин в бп (nan при !ok). Решение в ts[i] видит только состояние на ts[i]; опора — только по интервалам, закрытым к ts[i].
4	#include <stdint.h>
5	#include <stdlib.h>
6	#include <math.h>
7	#include <string.h>
8	typedef int64_t i64;
9	#define DAY 86400000LL
10	static i64 lb(const i64 *a, i64 n, i64 x) { i64 lo = 0, hi = n; while (lo < hi) { i64 m = (lo + hi) >> 1; if (a[m] < x) lo = m + 1; else hi = m; } return lo; }
11	static i64 asof(const i64 *a, i64 n, i64 x) { i64 lo = 0, hi = n; while (lo < hi) { i64 m = (lo + hi) >> 1; if (a[m] <= x) lo = m + 1; else hi = m; } return lo - 1; }
12	// взвешенное (временем) дерево Фенвика по рангам значений d
13	typedef struct { double *t; int n, lg; double tot; } BIT;
14	static void bit_init(BIT *b, int n) { b->n = n; b->t = calloc(n + 1, sizeof(double)); b->tot = 0; b->lg = 1; while ((1 << b->lg) <= n) b->lg++; }
15	static void bit_add(BIT *b, int r, double w) { b->tot += w; for (int i = r + 1; i <= b->n; i += i & -i) b->t[i] += w; }
16	static int bit_median(BIT *b) { // наименьший ранг с префиксом >= tot/2
17	  double need = b->tot / 2, acc = 0; int pos = 0;
18	  for (int k = b->lg; k >= 0; k--) { int np = pos + (1 << k); if (np <= b->n && acc + b->t[np] < need) { pos = np; acc += b->t[np]; } }
19	  return pos; // 0-индексный ранг = pos
20	}
21	// kind 0: медиана по времени за окно par (мс); 1: EMA с полупериодом par (мс); 2: медиана прошлых суток UTC (фикс на сутки). out[i] = опора на метке i или nan.
22	// rank[i] — ранг d[i] среди ok-значений (0..nr-1), dsorted[r] — значения по рангам.
23	void anchor(i64 M, const i64 *ts, const double *d, const uint8_t *ok, const int32_t *rank, const double *dsorted, int nr, int kind, double par, double *out) {
24	  for (i64 i = 0; i < M; i++) out[i] = NAN;
25	  if (kind == 0) {
26	    BIT b; bit_init(&b, nr); i64 tail = 0;
27	    for (i64 i = 0; i < M; i++) {
28	      if (i > 0 && ok[i - 1]) bit_add(&b, rank[i - 1], (double)(ts[i] - ts[i - 1]));
29	      while (tail < i && ts[tail + 1] <= ts[i] - (i64)par) { if (ok[tail]) bit_add(&b, rank[tail], -(double)(ts[tail + 1] - ts[tail])); tail++; }
30	      if (b.tot >= 0.95 * par) out[i] = dsorted[bit_median(&b)];
31	    }
32	    free(b.t);
33	  } else if (kind == 1) {
34	    double a = 0, el = 0; int st = 0;
35	    for (i64 i = 0; i < M; i++) {
36	      if (i > 0 && ok[i - 1]) {
37	        double dt = (double)(ts[i] - ts[i - 1]), al = exp(-dt * 0.6931471805599453 / par);
38	        a = st ? a * al + d[i - 1] * (1 - al) : d[i - 1]; st = 1; el += dt;
39	      }
40	      if (st && el >= par) out[i] = a;
41	    }
42	  } else {
43	    BIT b; bit_init(&b, nr); i64 cur = ts[0] / DAY, first = 0; double prev = NAN; i64 prevday = -10;
44	    for (i64 i = 0; i < M; i++) {
45	      i64 dy = ts[i] / DAY;
46	      if (i > 0 && ok[i - 1]) bit_add(&b, rank[i - 1], (double)(ts[i] - ts[i - 1])); // интервал относится к суткам своей левой метки
47	      if (dy != cur) { // сутки cur закончены: фиксируем медиану
48	        prev = (b.tot >= 0.95 * DAY) ? dsorted[bit_median(&b)] : NAN; prevday = cur;
49	        for (i64 j = first; j < i; j++) if (ok[j]) bit_add(&b, rank[j], -(double)(ts[j + 1] - ts[j]));
50	        b.tot = 0; first = i; cur = dy;
51	      }
52	      out[i] = (prevday == dy - 1) ? prev : NAN;
53	    }
54	    free(b.t);
55	  }
56	}
57	static double fcum_at(const i64 *pt, const double *cs, i64 n, i64 T) { i64 k = asof(pt, n, T); return k < 0 ? 0.0 : cs[k]; } // сумма ставок выплат с временем <= T
58	// Клетки одного якоря. Клетка c: thr[c] — порог в бп (k*круг), Dl[c] — задержка мс, To[c] — тайм-аут мс. Клетки сгруппированы по thr (список кандидатов перестраивается).
59	// mode 0 — кандидаты по списку, 1 — полный перебор (гейт «байт в байт»). Выход (на клетку × NH часов): sg gross бп, fg фандинг бп, cnt, ep, cr1, cr2; dropk (4 причины) на клетку.
60	// funding: pg/cg (Gate), pb/cb (Bybit; nb=0 — нет ноги) — времена выплат и накопленные ставки (доля, не бп).
61	void cells(i64 M, const i64 *ts, const double *gb, const double *ga, const double *bb, const double *ba, const uint8_t *ok, const double *d, const double *b, const double *gbw, const double *gaw, i64 tend, i64 t0, int NH,
